                      ? Math.min(item._saldo, item._saldo_reserva || item._saldo)
                      : item._saldo;
                    return [...prev, { estoque_produto_id: id, quantidade: String(qtdDefault) }];
                  });
                }
                setPendingOverrideId(null);
              }}

